    userId: suspended.userId,
  });

  return suspended;
}

/** Lifts a suspension. Reinstating an active member is a no-op. */
export async function reinstateMember(
  actor: Actor,
  input: MemberStatusInput,
): Promise<Member> {
  const member = await loadStatusTarget(actor, input);

  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/**
 * The guards suspension and reinstatement share: tenant scope, a live member,
 * `member:remove` on it, never oneself and never someone of higher rank.
 */
async function loadStatusTarget(
  actor: Actor,
  input: MemberStatusInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await memberRepo.findMemberById(input.orgId, input.memberId);
  if (!member || member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }

  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new PermissionDeniedError("member:remove", {
      allowed: false,
      action: "member:remove",
      resourceKind: "member",
      reason: "denied_by_role",
    });
  }

  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new PermissionDeniedError("member:remove", {
      allowed: false,
      action: "member:remove",
      resourceKind: "member",
      reason: "denied_by_role",
    });
  }

  return member;
}

