import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import { notify } from "@/server/services/notification-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { activityFilterSchema } from "@/schemas/activity";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
let off: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); off = registerActivityListeners(); });
afterAll(() => { off(); cleanup(); });

describe("suspend", () => {
  it("works", async () => {
    const t = await createTenant("susp-a", "growth");
    const viewer = (await memberRepo.findMember(t.org.id, t.userIds.viewer))!;
    const owner = (await memberRepo.findMember(t.org.id, t.userIds.owner))!;
    const s = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(s.status).toBe("suspended");
    expect(await memberService.resolveActor(t.userIds.viewer, t.org.id)).toBeNull();
    expect((await orgRepo.listOrgsForUser(t.userIds.viewer)).length).toBe(0);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    expect((await usageRepo.recomputeUsage(t.org.id)).seatsUsed).toBe(4);
    expect(await notify(t.org.id, "issue_assigned", [t.userIds.viewer, t.userIds.member], { title: "x", body: "y", href: "/", actorId: null })).toHaveLength(1);
    await expect(issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.viewer }) as never)).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id) as never);
    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.viewer })).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    const c = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi @viewer @member", mentionedUserIds: [t.userIds.viewer], parentId: null } as never);
    expect(c.mentionedUserIds).toEqual([t.userIds.member]);
    const again = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(again.updatedAt).toBe(s.updatedAt);
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow();
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow();
    const r = await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(r.status).toBe("active");
    expect(await memberService.resolveActor(t.userIds.viewer, t.org.id)).not.toBeNull();
    await new Promise((res) => setTimeout(res, 50));
    const acts = await activityRepo.listActivity(activityFilterSchema.parse({ orgId: t.org.id, action: ["member.suspended", "member.reinstated"], limit: 10, cursor: null }));
    expect(acts.items.map((a) => a.action).sort()).toEqual(["member.reinstated", "member.suspended"]);
    expect(acts.items[0]!.subjectId).toBe(viewer.id);
    // last owner rule
    const admin = (await memberRepo.findMember(t.org.id, t.userIds.admin))!;
    await memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: admin.id, role: "owner" });
    await memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: admin.id });
    await expect(memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow(/at least one owner/);
    // removed
    const member = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: member.id });
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: member.id })).rejects.toBeInstanceOf(NotFoundError);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(3);
    void notificationRepo;
  });
});
EOF
